-- The owner's payment queue, domain half (spec 339 §I, issue #549).
--
-- Numbered 0019, chained on 0018 (#556, #548 FX rates).
--
-- 1. `settles_item_id` (EARS-528/544): the per-item link from a reimbursement
--    transfer to the `personal_funds` item it settles. GENERATED by drizzle-kit
--    (column, FK, partial unique index, CHECK). The unique index is PARTIAL —
--    a refused or cancelled transfer moved no money, so it must not hold the
--    debt hostage; among live transfers one item is settled at most once.
-- 2. The capture trigger's value whitelist gains `settles_item_id` (HAND-WRITTEN:
--    `TG_ARGV` is replaced wholesale, so the whole list is restated — mirror in
--    `tools/lint/audit-coverage-allowlist.mjs`).
-- 3. EARS-545: the migration-0014 link guard is narrowed for `posted` items
--    only — a receipt may follow the posting; `refused` and `cancelled` stay
--    closed, and deletion of a retained link is unchanged (EARS-516).
-- 4. The one-time data step (EARS-528 revision note): every posted non-backfill
--    liability transfer written before this column existed is linked to its
--    single candidate — a posted, unsettled `personal_funds` item of the same
--    member, liability currency and liability amount. Any other (no candidate,
--    or more than one) STOPS the migration and names the transfer: the deploy
--    does not proceed until the owner links it. Production on 2026-11-17 holds
--    0 ledger operations, so the step is expected to link nothing there.
--

ALTER TABLE "core"."finance_intake_item" ADD COLUMN "settles_item_id" integer;--> statement-breakpoint
ALTER TABLE "core"."finance_intake_item" ADD CONSTRAINT "finance_intake_item_settles_item_id_finance_intake_item_id_fk" FOREIGN KEY ("settles_item_id") REFERENCES "core"."finance_intake_item"("id") ON DELETE no action ON UPDATE no action;--> statement-breakpoint
CREATE UNIQUE INDEX "finance_intake_item_settles_item_unique" ON "core"."finance_intake_item" USING btree ("settles_item_id") WHERE "core"."finance_intake_item"."settles_item_id" is not null and "core"."finance_intake_item"."status" not in ('refused', 'cancelled');--> statement-breakpoint
ALTER TABLE "core"."finance_intake_item" ADD CONSTRAINT "finance_intake_item_settles_transfer" CHECK ("core"."finance_intake_item"."settles_item_id" is null or ("core"."finance_intake_item"."kind" = 'transfer' and "core"."finance_intake_item"."settles_item_id" <> "core"."finance_intake_item"."id"));--> statement-breakpoint

CREATE OR REPLACE TRIGGER "finance_intake_item_audit"
	AFTER INSERT OR UPDATE OR DELETE ON "core"."finance_intake_item"
	FOR EACH ROW EXECUTE FUNCTION "core"."audit_row_change"(
		'id', 'source', 'source_ref', 'kind', 'status', 'occurred_on',
		'account_id', 'counter_account_id', 'amount', 'currency', 'paid_amount',
		'paid_currency', 'fee_amount', 'fee_currency', 'purpose_id',
		'project_id', 'product_id', 'counterparty_id', 'member_id', 'note',
		'already_paid', 'personal_funds', 'created_by', 'decided_by',
		'decided_at', 'refusal_reason', 'posted_by', 'posted_at', 'operation_id',
		'created_at', 'provenance', 'settles_item_id'
	);--> statement-breakpoint

-- EARS-545 narrows 0014's INSERT arm to `refused` / `cancelled`. Everything
-- else in the function is 0014's text unchanged.
CREATE OR REPLACE FUNCTION "core"."finance_document_link_retained"() RETURNS trigger
	LANGUAGE plpgsql
	SECURITY DEFINER
	SET search_path = pg_catalog, core
AS $$
DECLARE
	item_status text;
	document_state text;
	item_id integer;
BEGIN
	IF TG_OP = 'TRUNCATE' THEN
		RAISE EXCEPTION 'core.finance_document_link cannot be truncated: retained links are immutable (spec 339, EARS-516).';
	END IF;
	IF TG_OP = 'UPDATE' THEN
		RAISE EXCEPTION 'core.finance_document_link is never replaced; detach and attach through the module (spec 339, EARS-516).';
	END IF;

	item_id := CASE WHEN TG_OP = 'INSERT' THEN NEW.intake_item_id ELSE OLD.intake_item_id END;
	SELECT item.status, document.storage_state
	INTO item_status, document_state
	FROM core.finance_intake_item AS item
	JOIN core.finance_document AS document
		ON document.id = CASE WHEN TG_OP = 'INSERT' THEN NEW.document_id ELSE OLD.document_id END
	WHERE item.id = item_id
	FOR UPDATE OF item;

	IF TG_OP = 'INSERT' AND item_status IN ('refused', 'cancelled') THEN
		RAISE EXCEPTION 'core.finance_document_link cannot extend closed intake item % (spec 339, EARS-516, EARS-545).', item_id;
	END IF;
	IF TG_OP = 'DELETE'
		AND item_status IN ('posted', 'refused', 'cancelled')
		AND document_state <> 'pending_delete' THEN
		RAISE EXCEPTION 'core.finance_document_link % is retained by a terminal intake item (spec 339, EARS-516).', OLD.id;
	END IF;
	IF TG_OP = 'INSERT' THEN RETURN NEW; END IF;
	RETURN OLD;
END;
$$;--> statement-breakpoint

-- data-step:begin
-- A posted item is an immutable terminal record (0011's
-- `finance_intake_document_retained_row`), so the link is written with that
-- one guard lifted for the duration of this block and restored before it
-- ends — the capture trigger stays on, so every link written here is in the
-- journal. Run as the migrating role, which owns the table.
DO $data_step$
DECLARE
	transfer record;
	candidate integer;
	candidates integer;
	leftovers text := '';
BEGIN
	ALTER TABLE "core"."finance_intake_item" DISABLE TRIGGER "finance_intake_document_retained_row";
	FOR transfer IN
		SELECT t.id, t.member_id, t.currency, t.amount
		FROM core.finance_intake_item AS t
		JOIN core.finance_account AS a ON a.id = t.counter_account_id
		WHERE t.kind = 'transfer'
			AND t.status = 'posted'
			AND t.source <> 'backfill'
			AND t.settles_item_id IS NULL
			AND a.is_system
			AND a.kind = 'liability'
		ORDER BY t.id
	LOOP
		SELECT count(*), min(i.id)
		INTO candidates, candidate
		FROM core.finance_intake_item AS i
		WHERE i.status = 'posted'
			AND i.personal_funds
			AND i.member_id = transfer.member_id
			AND coalesce(i.paid_currency, i.currency) = transfer.currency
			AND coalesce(i.paid_amount, i.amount) + coalesce(i.fee_amount, 0) = transfer.amount
			AND NOT EXISTS (
				SELECT 1 FROM core.finance_intake_item AS s
				WHERE s.settles_item_id = i.id AND s.status NOT IN ('refused', 'cancelled')
			);
		IF candidates = 1 THEN
			UPDATE core.finance_intake_item SET settles_item_id = candidate WHERE id = transfer.id;
		ELSE
			leftovers := leftovers || format(' #%s (кандидатов: %s);', transfer.id, candidates);
		END IF;
	END LOOP;
	ALTER TABLE "core"."finance_intake_item" ENABLE TRIGGER "finance_intake_document_retained_row";
	IF leftovers <> '' THEN
		RAISE EXCEPTION 'EARS-528: liability transfers without a single settled item — link them before deploying:%', leftovers;
	END IF;
END
$data_step$;
-- data-step:end
